namespace BadWaters.Sim.Economy;

// Economy content (data/core/economy, generated by tools/gen_economy.py). Abstract game goods, recipes and
// quantities tuned for play: they model industrial capability (ore is not metal, metal is not an aerospace
// alloy), not real process data. The C# only evaluates the graph; every good, process and facility is data.

public sealed record ResourceDef(string Id, string Name, string Category, string Method, string RawGood);

public sealed record GoodSpec
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    /// <summary>0 raw, 1 intermediate, 2 refined, 3 industrial material, 4 part class, 5 finished / energy / service.</summary>
    public int Tier { get; init; }
    /// <summary>Transport class: bulk | general | high | grid.</summary>
    public string Weight { get; init; } = "general";
    public double Price { get; init; } = 1;
    public bool Storable { get; init; } = true;
}

public sealed record SubstituteDef(string Good, string Alt, double Ratio = 1, double Penalty = 0.2);

/// <summary>A recipe: inputs to outputs per batch at a facility type, with energy, labour, tech and tooling.</summary>
public sealed record ProcessDef
{
    public required string Id { get; init; }
    public required string Facility { get; init; }
    public Dictionary<string, double> Inputs { get; init; } = new();
    public Dictionary<string, double> Outputs { get; init; } = new();
    /// <summary>Electricity per batch (game units).</summary>
    public double Energy { get; init; }
    public Dictionary<string, double> Labour { get; init; } = new();
    public Dictionary<string, int> Tech { get; init; } = new();
    /// <summary>A tooling good that must be on hand (not consumed) for the process to run.</summary>
    public string? Tooling { get; init; }
    /// <summary>Extraction processes draw on a deposit of this resource.</summary>
    public string? Deposit { get; init; }
    public List<SubstituteDef> Substitutes { get; init; } = new();
}

public sealed record FacilityTypeDef
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public string Class { get; init; } = "";
    /// <summary>TargetPolicy class for this facility.</summary>
    public string TargetClass { get; init; } = "industrial";
    /// <summary>Batches per month per level.</summary>
    public double Capacity { get; init; }
    public double Energy { get; init; }
    public Dictionary<string, double> Labour { get; init; } = new();
    public Dictionary<string, double> Build { get; init; } = new();
    public double BuildMonths { get; init; } = 12;
    public double BuildCost { get; init; }
    /// <summary>Condition lost per month without maintenance.</summary>
    public double Decay { get; init; } = 0.01;
    /// <summary>Spares consumed per month per level to hold condition.</summary>
    public Dictionary<string, double> Spares { get; init; } = new();
    public double Storage { get; init; }
    /// <summary>Electricity supplied per month per level (power stations).</summary>
    public double SuppliesEnergy { get; init; }
    public double ConstructionCapacity { get; init; }
}

public sealed record FamilyBill(string Facility, Dictionary<string, double> Goods);
public sealed record FrameBill(string Facility, Dictionary<string, double> Goods, string Per, double Unit, string Spares);
public sealed record BillTemplates(Dictionary<string, FamilyBill> Families, Dictionary<string, FrameBill> Frames, Dictionary<string, Dictionary<string, double>> Parts, Dictionary<string, double> DefaultPart);

/// <summary>All economy content, indexed.</summary>
public sealed class EconomyCatalog
{
    public Dictionary<string, ResourceDef> Resources { get; } = new();
    public Dictionary<string, GoodSpec> Goods { get; } = new();
    public Dictionary<string, ProcessDef> Processes { get; } = new();
    public Dictionary<string, FacilityTypeDef> Facilities { get; } = new();
    public BillTemplates Bills { get; set; } = new(new(), new(), new(), new());

    private Dictionary<string, List<ProcessDef>>? _producers;
    /// <summary>Processes that output a good, the primary producer (largest share of its output) first.</summary>
    public IReadOnlyList<ProcessDef> Producers(string good)
    {
        _producers ??= Processes.Values.SelectMany(p => p.Outputs.Keys.Select(g => (g, p))).GroupBy(x => x.g)
            .ToDictionary(x => x.Key, x => x.Select(y => y.p).OrderByDescending(p => p.Outputs[x.Key] / p.Outputs.Values.Sum()).ThenBy(p => p.Id, StringComparer.Ordinal).ToList());
        return _producers.TryGetValue(good, out var l) ? l : (IReadOnlyList<ProcessDef>)Array.Empty<ProcessDef>();
    }
}
